content:
Package Manager（Git URL）

Unity エディターで Window → Package Manager → + → Add package from git URL:

https://github.com/achieveonepark/npc-mentality.git

manifest.json に直接追加

Packages/manifest.json を開き、dependencies に追加します:

{
  "dependencies": {
    "com.achieveonepark.npc-mentality": "https://github.com/achieveonepark/npc-mentality.git"
  }
}

クイックスタート

1. NPC にコンポーネントを追加

Inspector で NPC の GameObject に必要なコンポーネントを追加します。

Add Component → NPC Mentality → NPC Memory
Add Component → NPC Mentality → Emotion Controller
Add Component → NPC Mentality → Crowd NPC

2. プレイヤー行動を記録

using NpcMentality;

public class PlayerInteraction : MonoBehaviour
{
    public NPCMemory targetNpc;

    void StealItem()
    {
        targetNpc.Remember(EventType.Steal, weight: -3f);
    }

    void HelpVillager()
    {
        targetNpc.Remember(EventType.Help, weight: 5f);
    }
}

3. NPC の反応を読む

float attitude = targetNpc.GetAttitude();

if (attitude < -5f)
    dialogue.Say("また来たのか…荷物に触るなよ。");
else if (attitude > 5f)
    dialogue.Say("前回は助かったよ。");
else
    dialogue.Say("いらっしゃいませ。");

4. 時間システムを登録

シーンに空の GameObject を作り、WorldTimeSystem コンポーネントを追加します。

void Start()
{
    WorldTimeSystem.Instance.Register("Shop",
        openHour: 8,
        closeHour: 22,
        onOpen:  () => Debug.Log("店が開いた"),
        onClose: () => Debug.Log("店が閉まった")
    );
}

エディターウィンドウ

Tools → NPC Mentality メニューで 7 つのシステムの API リファレンスを確認できます。

サンプル

Package Manager で Samples → Basic Demo をインポートすると DemoUsage.cs が追加されます。7 つのシステムを 1 つのシーンで接続したサンプルコードです。

感情設定の 1 行で移動速度・アニメーター・まばたきが自動で変わります。

概要

従来:
  anim.Play("Idle");

NPC Mentality:
  emotion.Set(Emotion.Angry);
  → 自動: 歩行速度増加 / 頭が揺れる / 表情変化 / まばたき減少

EmotionType 列挙型

public enum EmotionType
{
    Neutral, Happy, Angry, Sad, Afraid, Surprised, Disgusted
}

感情別エフェクト

感情	NavMesh速度	アニメータートリガー	BlinkRate
Neutral	×1.0	"Idle"	1.0
Happy	×1.0	"Happy"	1.0
Angry	×1.5	"Angry"	0.3（減少）
Sad	×0.7	"Sad"	0.8
Afraid	×1.3	"Afraid"	1.5（増加）

サンプル

using NpcMentality;

public class NPCReaction : MonoBehaviour
{
    private NPCMemory _memory;
    private EmotionController _emotion;

    private void Awake()
    {
        _memory  = GetComponent<NPCMemory>();
        _emotion = GetComponent<EmotionController>();
    }

    public void OnTalkWithPlayer()
    {
        float attitude = _memory.GetAttitude();

        if (attitude < -8f)      _emotion.Set(EmotionType.Angry);
        else if (attitude < -2f) _emotion.Set(EmotionType.Disgusted);
        else if (attitude > 8f)  _emotion.Set(EmotionType.Happy);
        else                     _emotion.Set(EmotionType.Neutral);
    }

    public void OnCombatStart() => _emotion.Set(EmotionType.Afraid);
    public void OnCombatEnd()   => _emotion.Set(EmotionType.Neutral);
}

NPC がプレイヤーの行動を記憶し、累積態度（Attitude）を計算します。

概要

プレイヤー:
- 商人の物を3回盗んだ
- 村人を助けた

NPC:
  商人: "また来たのか…荷物に触るなよ。"
  村人: "前回は助かったよ。"

コンポーネント

NPCMemory — MonoBehaviour。NPC の GameObject に追加します。

フィールド	型	デフォルト	説明
MaxMemories	int	20	最大記憶数。超過時は最も古いものを削除
memories	List<MemoryEvent>	—	記憶リスト（Inspector で確認可能）

API

Remember

void Remember(EventType type, float weight = 1f, string context = "")

プレイヤー行動を記録します。

パラメーター	説明
type	行動タイプ（EventType 列挙型）
weight	態度への影響。正 = 友好的、負 = 敵対的
context	任意の説明文字列

npc.Remember(EventType.Steal,  weight: -3f);
npc.Remember(EventType.Help,   weight:  5f);
npc.Remember(EventType.Attack, weight: -10f);
npc.Remember(EventType.Gift,   weight:  3f);

GetAttitude

float GetAttitude()

全記憶の weight 合計を返します。

float attitude = npc.GetAttitude();
// attitude > 0  → 友好的
// attitude == 0 → 中立
// attitude < 0  → 敵対的

HasMemory

bool HasMemory(EventType type)

特定タイプの記憶が存在するか確認します。

if (npc.HasMemory(EventType.Steal))
    dialogue.Say("また来たのか…");

ForgetOldest

void ForgetOldest()

最も古い記憶を手動で削除します。MaxMemories 超過時に自動呼び出しされます。

EventType 列挙型

public enum EventType
{
    None, Steal, Help, Attack, Trade,
    Talk, Threaten, Gift, Kill, Rescue
}

サンプル

using NpcMentality;

public class ShopKeeper : MonoBehaviour
{
    private NPCMemory _memory;

    private void Awake() => _memory = GetComponent<NPCMemory>();

    public void OnPlayerSteals()
    {
        _memory.Remember(EventType.Steal, weight: -3f, context: "貴重な薬草");

        if (_memory.GetAttitude() < -6f)
            GuardSystem.Alert(transform.position);
    }

    public string GetGreeting()
    {
        return _memory.GetAttitude() switch
        {
            < -5f => "出て行け。",
            < 0f  => "何が入り用だ？",
            < 5f  => "いらっしゃいませ。",
            _     => "あなたのようなお客様が増えるといいですね！"
        };
    }
}

プレイヤーの行動パターンを分析して、文脈に合ったクエストを自動生成します。

概要

プレイヤー:
  - 森によく行く
  - オオカミをたくさん倒す

生成:
  "森の近くに奇妙なオオカミが現れた。"

ランダムクエストよりもずっと自然。

API

GenerateQuest

QuestData GenerateQuest(EventType trigger, string subject = "creature")

QuestData q = generator.GenerateQuest(EventType.Kill, "wolf");
// → "森の近くに奇妙なwolfが現れた。"

OnQuestGenerated イベント

generator.OnQuestGenerated += quest =>
{
    QuestUI.Show(quest.Title, quest.Description);
    QuestLog.Add(quest);
};

デフォルトテンプレート

EventType	生成例
Kill	"森の近くに奇妙な {subject} が現れた。"
Steal	"商人地区から荷物が消えた。"
Help	"また助けの手が必要だ。"
Rescue	"危険にさらされた人がいる。"

サンプル

using NpcMentality;

public class PlayerBehaviorTracker : MonoBehaviour
{
    public AIQuestGenerator questGenerator;
    private int _wolfKillCount = 0;

    public void OnWolfKilled()
    {
        _wolfKillCount++;
        if (_wolfKillCount >= 5)
        {
            questGenerator.GenerateQuest(EventType.Kill, "wolf");
            _wolfKillCount = 0;
        }
    }
}

NPC 間の友人関係を通じて感情が伝播します。

概要

A がプレイヤーを嫌う
    ↓
A の友人 B も影響を受ける (×0.5)
    ↓
B の友人 C も少し影響を受ける (×0.25)

結果: 商人の村全体が敵対的になる

RelationshipGraph

NPC 間の友人関係を保存する ScriptableObject です。

作成: Project パネルで右クリック → Create → NPC Mentality → Relationship Graph

API

graph.AddFriendship("merchant_a", "villager_b");
graph.AddFriendship("villager_b", "blacksmith_c");

List<string> friends = graph.GetFriends("merchant_a");

RelationshipContagion

静的ヘルパークラス。態度変化を友人ネットワーク全体に伝播します。

Propagate

static void Propagate(
    string sourceNpcId,
    float attitudeChange,
    RelationshipGraph graph,
    Dictionary<string, NPCMemory> allNpcs,
    int depth = 2,
    float decay = 0.5f
)

パラメーター	説明
sourceNpcId	態度変化の発生源 NPC ID
attitudeChange	伝播する態度変化量
graph	友人関係グラフ
allNpcs	全 NPC の NPCMemory 辞書
depth	伝播深度（デフォルト 2）
decay	段階ごとの減衰率（デフォルト 0.5）

サンプル

using NpcMentality;
using System.Collections.Generic;

public class VillageManager : MonoBehaviour
{
    public RelationshipGraph graph;
    private Dictionary<string, NPCMemory> _npcs = new();

    private void Start()
    {
        graph.AddFriendship("merchant", "innkeeper");
        graph.AddFriendship("innkeeper", "blacksmith");

        foreach (var npc in FindObjectsOfType<NPCMemory>())
            _npcs[npc.gameObject.name] = npc;
    }

    public void OnPlayerAttacksMerchant()
    {
        _npcs["merchant"].Remember(EventType.Attack, weight: -10f);

        RelationshipContagion.Propagate(
            sourceNpcId: "merchant",
            attitudeChange: -10f,
            graph: graph,
            allNpcs: _npcs,
            depth: 2,
            decay: 0.5f
        );
        // merchant: -10, innkeeper: -5, blacksmith: -2.5
    }
}

情報が NPC の間を流れるにつれて内容が変化していきます。

概要

プレイヤーがボスを倒す
    ↓
NPC1: "誰かがドラゴンを倒したって？"
    ↓
NPC2: "違うよ、魔法使いらしいよ"
    ↓
NPC3: "魔王が死んだらしい"

コンポーネント

RumorSystem — MonoBehaviour。

フィールド	型	デフォルト	説明
MutationChance	float	0.3f	変形確率（0〜1）
MutationSuffixes	List<string>	デフォルト4つ	変形時に追加される文章
ActiveRumors	List<RumorData>	—	現在進行中の噂リスト

API

rumorSystem.SpreadRumor("誰かがドラゴンを倒した", sourceNpcId: "player");

var rumor = rumorSystem.ActiveRumors[^1];
rumorSystem.PassRumor(rumor, "npc_01");

サンプル

using NpcMentality;

public class RumorDemo : MonoBehaviour
{
    public RumorSystem rumorSystem;
    public string[] npcIds = { "blacksmith", "innkeeper", "farmer", "guard" };

    public void OnPlayerKillsDragon()
    {
        rumorSystem.SpreadRumor("誰かがドラゴンを倒した", "player");
        StartCoroutine(SpreadToVillage());
    }

    private System.Collections.IEnumerator SpreadToVillage()
    {
        var rumor = rumorSystem.ActiveRumors[^1];
        foreach (string npcId in npcIds)
        {
            yield return new WaitForSeconds(2f);
            rumorSystem.PassRumor(rumor, npcId);
        }
    }
}

ヒント

MutationChance = 0f — 変形なしで事実のみ伝播します。

MutationChance = 1f — 毎回必ず変形します。

RelationshipContagion と組み合わせると噂の内容と感情が同時に広がります。

ゲーム内の時間の流れに応じて、店の開閉や NPC のスケジュールを自動管理します。

概要

08:00 → 店が開く
12:00 → NPC が昼食
22:00 → 店が閉まる
02:00 → 盗賊が登場

コンポーネント

WorldTimeSystem — MonoBehaviour シングルトン。シーンに 1 つだけ配置します。

フィールド	型	デフォルト	説明
TimeScale	float	1f	時間倍速
CurrentHour	float	0f	現在時刻（0〜24、読み取り専用）

API

Register

WorldTimeSystem.Instance.Register(
    "Shop",
    openHour: 8,
    closeHour: 22,
    onOpen:  () => shopkeeper.Open(),
    onClose: () => shopkeeper.Close()
);

IsOpen

if (WorldTimeSystem.Instance.IsOpen("Shop"))
    ShowShopUI();

OnHourChanged イベント

WorldTimeSystem.Instance.OnHourChanged += hour =>
    Debug.Log($"現在時刻: {Mathf.FloorToInt(hour):D2}:00");

サンプル

using NpcMentality;

public class VillageScheduler : MonoBehaviour
{
    public CrowdNPC[] villagers;
    public GameObject thiefPrefab;

    private void Start()
    {
        var wt = WorldTimeSystem.Instance;
        wt.Register("Day", openHour: 6, closeHour: 22,
            onOpen:  () => { foreach (var v in villagers) v.enabled = true; },
            onClose: () => { foreach (var v in villagers) v.enabled = false; });

        wt.Register("Thief", openHour: 2, closeHour: 4,
            onOpen:  () => Instantiate(thiefPrefab, GetAlleyPosition(), Quaternion.identity),
            onClose: () => DespawnThieves());
    }
}
